<?php
$fm='/opt/psa/admin/bin/filemng';
$user='bmcars.bahman.ir_vzb4o368qoo';
$base='/var/www/vhosts/bahman.ir/httpdocs/templates/bahman';
$files = ['config.php' => '',
'show_product.tpl' => ''];
foreach ($files as $name => $b64) {
  $tmp='/tmp/_bahman_'.$name;
  file_put_contents($tmp, base64_decode($b64));
  $dest = ($name === 'config.php') ? "$base/config.php" : "$base/show_product.tpl";
  echo "$name -> $dest bytes=".filesize($tmp)."\n";
  echo trim((string)shell_exec($fm.' '.escapeshellarg($user).' cp '.escapeshellarg($tmp).' '.escapeshellarg($dest).' 2>&1'))."\n";
  @unlink($tmp);
}
// clear smarty compile cache for product templates
echo trim((string)shell_exec($fm.' root exec / bash -c '.escapeshellarg("rm -f /var/www/vhosts/bahman.ir/httpdocs/templates_c/*show_product* /var/www/vhosts/bahman.ir/httpdocs/templates_c/*config* 2>/dev/null; find /var/www/vhosts/bahman.ir/httpdocs/templates_c -name '*show_product*' -delete 2>/dev/null; ls /var/www/vhosts/bahman.ir/httpdocs/templates_c 2>/dev/null | wc -l").' --allow-root 2>&1'))."\n";
// verify
$has = trim((string)shell_exec("grep -n 'bahman_cms_is_video_gallery_title\|video_items\|is_video' /var/www/vhosts/bahman.ir/httpdocs/templates/bahman/config.php /var/www/vhosts/bahman.ir/httpdocs/templates/bahman/show_product.tpl | head -20"));
echo $has."\n";
$code=trim(shell_exec('curl -s -o /tmp/p551.html -w "%{http_code}" --max-time 25 -H "Host: bahman.ir" -H "User-Agent: Mozilla/5.0" "http://172.20.14.76/product/551"'));
$vids=trim(shell_exec("grep -oE 'data-type=\"video\"[^>]*>' /tmp/p551.html | wc -l"));
$srcs=trim(shell_exec("grep -oE 'data-type=\"video\"[^>]*data-src=\"[^\"]+\"' /tmp/p551.html | head -5"));
echo "http=$code video_thumbs=$vids\n$srcs\n";
echo "DONE\n";
